"""Ed25519 keys to sign and verify envelopes (mandates, receipts). Keys are generated by the
caller; nothing here stores them.
"""
from __future__ import annotations

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
    Ed25519PublicKey,
)

from ask_first.canonical import canonical


def generate_pair() -> tuple[Ed25519PrivateKey, Ed25519PublicKey]:
    priv = Ed25519PrivateKey.generate()
    return priv, priv.public_key()


def public_key_hex(pub: Ed25519PublicKey) -> str:
    return pub.public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


def public_key_from_hex(hexstr: str) -> Ed25519PublicKey:
    return Ed25519PublicKey.from_public_bytes(bytes.fromhex(hexstr))


def sign_envelope(priv: Ed25519PrivateKey, envelope: dict) -> str:
    """Signs the canonical bytes (RFC 8785) of the envelope. Returns the signature as hex."""
    return priv.sign(canonical(envelope)).hex()


def verify_signature(pub: Ed25519PublicKey, envelope: dict, signature_hex: str) -> bool:
    """True if `signature_hex` is a valid Ed25519 signature by `pub` over the canonical envelope."""
    try:
        pub.verify(bytes.fromhex(signature_hex), canonical(envelope))
        return True
    except (InvalidSignature, ValueError):
        return False
